  var BIG = { walls: 1, wallsScanAt: 1, farmHide: 1, barbs: 1, barbsFull: 1, villOwners: 1, farmLog: 1, outCmds: 1, villages: 1, buildings: 1, vidByCoord: 1, unitinfo: 1, backHome: 1, scavOut: 1, ecoTroops: 1,
    ecoSnaps: 1, ecoMoves: 1, ecoDays: 1, ecoLootLog: 1, prodReal: 1, resAutoLog: 1, snobLog: 1, pktLog: 1, mapDraw: 1, farmResume: 1,
    grpList: 1, repStates: 1, mapMarks: 1, mapArrows: 1, mapLetters: 1, wallsManual: 1, scoutDone: 1, labelTried: 1,
    incSeen: 1, supSeen: 1, alerts: 1, farmEvents: 1, farmNear: 1, gcState: 1, tesSnap: 1 };   // gcState/tesSnap: GC e Tesouraria (dezenas a centenas de KB)
  var bigMem = null, idbDb = null, bigBc = null, bigInitDone = false;   // bigMem = {chave: texto JSON} quando o IndexedDB está ativo
