  // por conta também: a mesma aba pode trocar de conta (entrar/sair da substituição) e levaria aldeias, horários feitos…
  function ssKey(k) { return 'agtw_' + (ACCT ? ACCT + '_' : '') + k; }
  function ssGet(k) { try { return JSON.parse(sessionStorage.getItem(ssKey(k)) || 'null'); } catch (e) { return null; } }
