    resReserve: 0,        // quanto deixar em quem manda (de cada recurso)
    resSplit: 'prop',     // 'prop' = proporcional ao que cada um tem; 'near' = o mais perto primeiro
    scav: null,           // 🧺 coleta: {on, group, maxH, units, keep, method, margin, batch}
    dist: null,           // 📤 distribuir: {list: [{id, src, group, res: {wood, stone, iron}, keep, fill (%), auto: {on, r, over, h}}]}
    pala: null,           // ⚜ paladino: {auto: 'off'|'n'|'times', n, af, at, times} (quantas vezes por dia ler a estátua)
    roles: null,          // aviso ATK/DEF no Comando/Noblar: {on, atk: [ids de grupo], def: [ids]} (null = chuta pelo nome)
