    resAutoN: 3, resAutoFrom: '07:00', resAutoTo: '23:00', resAutoTimes: '08:00, 14:00, 20:00',
    ovf: null,            // 🌊 desafogar armazém: {on, every, unit, group, trig, down, fill, maxD}
    relicDiag: false,     // 🐞 Tesouraria (P0): só REGISTRA no log o que as telas de relíquia/bandeira mostram e respondem
