    if (!manual && n > c.snipeRetries) {
      return { status: 'failed', error: why + (c.snipeRetries ? ', acabaram as ' + c.snipeRetries + ' tentativas automáticas' : '') };
    }
    var p = snipeRetryPlan(s.returnAt, now(), homeAt, {
      leadMs: c.lookaheadSec * 1000 + 10000, windowMs: c.cancelWindowMin * 60000, durMs: cmd.durMs || cmd.estDur
    });
    if (!p) return { status: 'failed', error: why + ', não dá mais tempo de outra tentativa antes do retorno ' + fmt(s.returnAt, { date: false }) };
    // esquiva: sair depois que o ataque cai não protege nada
    if (s.dodge && s.before && p.send > s.before - 5000) return { status: 'failed', error: why + ', a nova tentativa sairia depois do ataque (' + fmt(s.before, { date: false, ms: false }) + '): a esquiva não vale mais' };
    var set = {}, snipe = {};
