  /* ---------- calibração ---------- */
  function readCalib() { return lsGet('calib', []); }
  function addCalibSample(b, kind) {
    if (!isFinite(b) || Math.abs(b) > 3000) return;
    var s = readCalib();
    // Com base já formada (≥3), rejeita leitura muito fora do padrão: provável pico de contenção
    // (operação com várias abas). Mantém a calibração representando o envio isolado (preciso).
    if (s.length >= 3) {
      var st = calibStats(s), tol = Math.max(150, 4 * (st.spread || 0));
      if (Math.abs(b - st.bias) > tol) {
        log('amostra de calibração DESCARTADA (fora do padrão):', Math.round(b) + 'ms', 'vs médio', Math.round(st.bias) + 'ms', '(tol ±' + Math.round(tol) + ')');
        return;
      }
    }
    s.push({ b: Math.round(b), kind: kind, at: Date.now() });
    while (s.length > 20) s.shift();
    lsSet('calib', s);
    log('amostra de calibração', kind, Math.round(b) + 'ms');
  }
  // Diagnóstico persistente: cada aba de envio grava aqui (sobrevive ao fechamento da aba);
