    lsSet('botStopLast', now());
    try { feedPush('⛔', 'captcha (' + String(where).replace(/^.*página\s*/, '').slice(0, 30) + '): tudo parado'); } catch (e) {}
    log('⛔ verificação do jogo (captcha) detectada em ' + where + ', Agendador parado');
