  /** Telas que só abrem com premium (Visualizações de tropas, edifícios, chegando, comandos, transporte; coleta em massa; pedido do mercado). */
  function needsPremium(url) { return /screen=overview_villages.*[?&]mode=(units|buildings|incomings|commands|trader)\b/.test(url) || /[?&]mode=(scavenge_mass|call)\b/.test(url); }
