      try { if (barbsFull.length) { var bid = {}; barbsFull.forEach(function (b) { bid[String(b[0])] = 1; }); var np = wallsPrune(function (id) { return !bid[String(id)]; }); if (np) log('muralhas: ' + np + ' aldeia(s) não são mais bárbaras, marcação tirada'); } } catch (e) { log('muralhas:', e); } lsSet('villOwners', { at: Date.now(), o: owners }); saveQueueNames(); barbSet = null; othersMap = null;
