    '#agtw-btn{position:fixed;right:0;top:38%;writing-mode:vertical-rl;border-radius:8px 0 0 8px!important;padding:10px 5px!important;z-index:99990;display:flex;align-items:center;gap:7px;background:#603000;color:#fff;border:2px solid #c1a264;border-radius:20px;',
    'padding:6px 14px;font:bold 12px Verdana;cursor:pointer;box-shadow:0 2px 8px rgba(0,0,0,.4);user-select:none;transition:background .2s}',
    '#agtw-btn:hover{background:#7d3f00}',
    '#agtw-btn{touch-action:none}#agtw-btn.left{right:auto;left:0;border-radius:0 8px 8px 0!important}',
    '#agtw-btn.drag{cursor:grabbing;opacity:.85;box-shadow:0 4px 16px rgba(0,0,0,.55);transition:none}',
    '#agtw-btn .n{background:#c00;border-radius:9px;padding:0 6px;font-size:11px}',
    '#agtw-btn .nx{font:bold 11px monospace;opacity:.9}#agtw-btn .nx:empty{display:none}',
    '#agtw-btn.soon{background:#9a3412;border-color:#fdba74}',
    '#agtw-btn.paused .n{background:#78716c}',
    // painel estreito (classe "narrow" posta pelo dock(): conteúdo < ~560 px): grade de 3 vira 2; a onda da Operação em
