      el.dataset.pickDone = '1';
      var b = h('button', { type: 'button', class: 'agtw-pick', title: 'Escolher no mapa: clique aqui e depois numa aldeia' }, '⌖');
      b.dataset.pick = pickSel(el);
      // campo + ⌖ na mesma linha (o campo ocupa 100%: sozinho o botão cairia para baixo)
