    coordPickStop();
    var id = el.id || '', multi = el.tagName === 'TEXTAREA' || !!el.dataset.spPaste || id in PICK_MULTI;
    coordPick = { sel: sel, multi: multi, sep: PICK_MULTI[id] || (el.tagName === 'TEXTAREA' ? ' ' : ' '), label: pickLabel(el) };
