    var where = function (it) { var p = o.pos[it.key]; return p && p.s && secIds[p.s] ? p.s : ''; };
    var sortKey = function (it) { var p = o.pos[it.key]; return p && p.i != null ? p.i : 1e15 + it.t; };   // arrumados primeiro; o resto na ordem de envio
