    var r = villageRoles(vid, again), u = unitsIn(spec), notes = [];
    var nm = function (l) { return l.map(function (k) { return UNIT_PT[k] || k; }).join(', '); }, gn = function (l) { return l.map(function (g) { return esc(roleGroupName(g)); }).join(', '); };
    if (r.def.length) {
      var off = Object.keys(u).filter(function (k) { return OFF_U[k]; });
      if (isAtk) notes.push(['warn', '🛡 <b>Aldeia de DEFESA</b> (' + gn(r.def) + '): você está mandando um <b>ataque</b> dela' + (off.length ? ', com ' + nm(off) : '') + '.']);
      else if (off.length) notes.push(['warn', '🛡 <b>Aldeia de DEFESA</b> (' + gn(r.def) + ') mandando <b>' + nm(off) + '</b>.']);
    }
