      var df = Object.keys(u).filter(function (k) { return DEF_U[k]; });
      if (df.length) notes.push(['warn', '⚔ <b>Aldeia de ATAQUE</b> (' + gn(r.atk) + ') mandando <b>' + nm(df) + '</b> (tropa de defesa).']);
