      var parts = fakeParts(), main = parts.filter(function (pt) { return pt.need; })[0];
      var unitPop = {}, fu = cfg().fakeUnit, mg = cfg().fakeMarginPct, barbs = {}, owned = fakeOwned(), skipT = {};
      Object.keys(ui.unitInfo).forEach(function (u) { unitPop[u] = ui.unitInfo[u].pop; });
