  var tradeIncMem = null;
  function tradesIncoming(inBorrow) {   // inBorrow: já dentro de um withGroup que vai devolver o grupo no fim (não devolve 2×)
    if (tradeIncMem && Date.now() - tradeIncMem.at < 60000) return Promise.resolve(tradeIncMem.m);
    if (!premiumOn()) return Promise.resolve(null);
    var t0 = now();
    // group=0 (todas as aldeias) vira o grupo selecionado: withGroup devolve o seu depois (se o seu não for "todas")
    var get = function () { return fetchText(gameUrl(GD.village.id, 'overview_villages', '&mode=trader&type=inc&page=-1&group=0')); };
    return (inBorrow ? get() : withGroup(0, get)).then(function (html) {
      var doc = new DOMParser().parseFromString(html, 'text/html'); if (!$q('#trades_table', doc) && !/mode=trader/.test(html)) return null;
      var m = {}, t = now();
      parseTrades(doc, t0).forEach(function (e) {
        if (!e.toId || e.arr <= t) return;
        var o = m[e.toId] || (m[e.toId] = { wood: 0, stone: 0, iron: 0 }); RES.forEach(function (r) { o[r] += e.res[r] || 0; });
      });
      tradeIncMem = { at: Date.now(), m: m }; return m;
    }, function (e) { log('recursos: não li os transportes chegando (' + e.message + '), uso a previsão do Pedido'); return null; });
  }
  /** Troca o "chegando" do Pedido pelos transportes de verdade (se lidos). */
  function realIncoming(cp, inc) {
    if (inc && cp && cp.village && cp.village.id) cp.incoming = Object.assign({ wood: 0, stone: 0, iron: 0 }, inc[String(cp.village.id)] || {});
    return cp;
  }
  /** Lê a página do Pedido: a aldeia destino (game_data da página), o que está chegando, os grupos e os fornecedores. */
  function parseCallPage(html) {
    var doc = new DOMParser().parseFromString(html, 'text/html'), v = null;
    var i = html.indexOf('"village":{"id":');
    if (i >= 0) {
      var s = html.slice(i, i + 3000), g = function (k) { var m = s.match(new RegExp('"' + k + '":(\\d+)')); return m ? +m[1] : 0; };
      var cm = s.match(/"coord":"(\d+\|\d+)"/), nm = s.match(/"name":"((?:[^"\\]|\\.)*)"/);
      v = { id: g('id'), wood: g('wood'), stone: g('stone'), iron: g('iron'), storage: g('storage_max'), coord: cm ? cm[1] : '',
        name: nm ? JSON.parse('"' + nm[1] + '"') : '' };
    }
    var sm = html.match(/CallResources\.res_schedule\s*=\s*(\{.*?\});\s*\n/), sched = null;
    try { sched = sm ? JSON.parse(sm[1]) : null; } catch (e) {}
    var incoming = resIncoming(sched);
    if (!sched) incoming = { wood: numText($q('#total_wood', doc)), stone: numText($q('#total_stone', doc)), iron: numText($q('#total_iron', doc)) };
    var groups = $qa('.group-menu-item[data-group-id]', doc).map(function (a) {
      return { id: a.dataset.groupId, name: a.textContent.replace(/[\[\]<>]|&[lg]t;/g, '').trim() };
    });
    var sup = $qa('tr.supply_location[data-village]', doc).map(function (tr) {
      var res = {}, tds = tr.querySelectorAll('td');
      RES.forEach(function (r) { var td = $q('td[data-res-type="' + r + '"]', tr); res[r] = td ? parseInt(td.dataset.res, 10) || 0 : 0; });
      var a = $q('a', tr);
      return { id: +tr.dataset.village, name: a ? a.textContent.trim() : '', ms: durMs(tds[1] && tds[1].textContent), cap: parseInt(tr.dataset.capacity, 10) || 0, res: res };
    });
    // outras páginas (mais de "Aldeias por página"): os links da paginação, em ordem (a atual não é link)
    var pages = []; $qa('a.paged-nav-item[href]', doc).forEach(function (a) { var hr = a.getAttribute('href'), m = hr.match(/[?&]page=(\d+)/); if (m && !pages.some(function (x) { return x.n === +m[1]; })) pages.push({ n: +m[1], href: hr }); });
    pages.sort(function (a, b) { return a.n - b.n; });
    return { village: v, incoming: incoming, groups: groups, sup: sup, pages: pages, form: !!$q('form[name="call-resources"]', doc) };
  }
  function callUrl(vid, group) { return gameUrl(vid, 'market', '&mode=call&order=distance&dir=ASC&target_id=0' + (group != null ? '&group=' + group : '')); }
  function fetchCall(vid, group) {
    return fetchText(callUrl(vid, group)).then(function (html) {
      var p = parseCallPage(html);
      if (!p.form) throw new Error('não abriu o Pedido do mercado' + (p.village && p.village.id === vid ? ' (tem mercado?)' : ''));
      if (p.groups.length) lsSet('resGroups', p.groups);
      return p;
    });
  }
  function resGroups() { return lsGet('resGroups', []); }
  /** Grupos com o nome ATUAL: o menu "Grupos:" das Visualizações (e do Pedido): atualiza a lista guardada, sem requisição. */
  /**
   * ⟳ grupos: a MESMA lista da janelinha "Grupos de aldeias" do jogo (villageDock: TribalWars.get em
   * screen=groups&mode=overview&ajax=load_group_menu → {result: [{group_id, name, type}]}). 1 pedido, de qualquer página,
   * sem trocar o grupo selecionado. (A tela Visualizações → Grupos não tem o menu "Grupos: […]", por isso não dava.)
   */
  function refreshGroups() {
    if (botStopped()) return Promise.reject(new Error('Agendador parado: verificação do jogo (captcha)'));
    return new Promise(function (ok, bad) {
      if (!W.TribalWars || !W.TribalWars.get) return bad(new Error('TribalWars.get indisponível'));
      // como o jogo chama: tela + parâmetros (o TribalWars.get só aceita endereço começando com "/"; "https://…" ele
      // entendia como nome de tela → "A solicitação falhou"). Ele mesmo põe a aldeia e o t= do sitter.
      W.TribalWars.get('groups', { mode: 'overview', ajax: 'load_group_menu' }, function (d) {
        var l = ((d && (d.result || (d.response && d.response.result))) || []).filter(function (g) { return g && g.type !== 'separator' && g.group_id != null; })
          .map(function (g) { return { id: String(g.group_id), name: String(g.name).trim() }; });
        if (!l.length) return bad(new Error('o jogo não devolveu os grupos'));
        lsSet('resGroups', l); grpListClear('⟳ grupos'); ok(l);   // ⟳ também relê as aldeias de cada grupo (na próxima vez que usar)
      }, function (e) { bad(new Error(e && typeof e === 'object' ? String(e.error || e.message || e.statusText || 'o jogo recusou') : String(e || 'falhou'))); });
    });
  }
  /** Botão "⟳ grupos" (Recursos e Coleta): lê e redesenha a aba. */
  function groupsBtnHtml() { return '<button class="ib gref" data-grp-refresh title="Atualizar a lista de grupos (1 leitura da Visualizações): para grupos que você acabou de criar ou renomear no jogo">⟳ grupos</button>'; }
  function bindGroupsBtn(bd) {
    var b = $q('[data-grp-refresh]', bd); if (!b) return;
    b.onclick = function (e) {
      e.preventDefault(); b.disabled = true; b.textContent = 'lendo…';
      refreshGroups().then(function (l) { toast(l.length + ' grupos', 'ok'); render(); }, function (er) { toast('Grupos: ' + er.message, 'bad'); b.disabled = false; b.textContent = '⟳ grupos'; });
    };
  }
  function groupsFromDoc(doc) {
    var l = $qa('.group-menu-item[data-group-id]', doc).map(function (a) { return { id: a.getAttribute('data-group-id'), name: a.textContent.replace(/[\[\]<>]|&[lg]t;/g, '').trim() }; })
      .filter(function (g) { return g.name; });
    if (l.length) lsSet('resGroups', l);
    return l;
  }
  /** Pede `sends` para a aldeia vid (1 POST, como o botão "Requisitar recursos" do jogo). */
  function postCall(vid, sends) {
    var body = 'target_id=0';
    sends.forEach(function (s) {
      RES.forEach(function (r) { body += '&' + encodeURIComponent('resource[' + s.id + '][' + r + ']') + '=' + s[r]; });
      body += '&select-village=' + s.id;
    });
    body += '&h=' + GD.csrf;
    var url = '/game.php?village=' + vid + '&screen=market&ajaxaction=call&h=' + GD.csrf;   // TribalWars.post já põe o t= do sitter
    return new Promise(function (ok, bad) {
      if (botStopped()) return bad(new Error('Agendador parado: verificação do jogo (captcha)'));
      if (W.TribalWars && W.TribalWars.post) W.TribalWars.post(url, null, body, function (r) { tradeIncMem = null; ok(r || {}); }, function (e) { bad(new Error(String((e && e.error) || e || 'o jogo recusou o pedido').replace(/<[^>]+>/g, ' ').trim())); });
      else bad(new Error('TribalWars.post indisponível'));
    });
  }
  function sumRes(o) { return (o.wood || 0) + (o.stone || 0) + (o.iron || 0); }
  function sleep(ms) { return new Promise(function (r) { wt.set(r, ms); }); }   // relógio do Worker: aba em segundo plano não é freada
  /** Pausa entre as requisições de recursos, academia, repasse e coleta (1,5 a 3,5 s): rodam poucas vezes por dia, sem pressa. */
  function reqGap() { return sleep((1500 + Math.random() * 2000) * gapK()); }
  function gapK() { var k = W.__agtwDebug && W.__agtwGapK; return typeof k === 'number' && k >= 0 ? k : 1; }   // só nos testes (modo depuração): encurta as pausas
  /**
   * Aldeias de um grupo pela lista do seletor de aldeias do jogo (VillageGroups.villageSelect: POST groups /
   * load_villages_from_group). Só lista: não troca o grupo selecionado, ao contrário da visão geral com &group=.
   */
  /**
   * Esquece as aldeias guardadas de cada grupo (o próximo uso relê: 1 leitura por grupo). Chamado no ⟳ dos grupos, ao abrir
   * a página de grupos do jogo e quando o jogo grava uma mudança de grupo (caixa "Grupos - Afiliação" da aldeia).
   */
  function grpListClear(why) { if (Object.keys(lsGet('grpList', {}) || {}).length) { lsSet('grpList', {}); log('grupos: aldeias de cada grupo serão relidas (' + why + ')'); } }
  /** Sem requisição: página de grupos aberta e mudança de grupo gravada pelo jogo (aviso do jQuery do próprio jogo). */
  function watchGroupEdits() {
    if (SCREEN === 'groups' || (SCREEN === 'overview_villages' && PARAMS.get('mode') === 'groups')) grpListClear('página de grupos aberta');
    try {
      if (W.jQuery) W.jQuery(document).on('ajaxComplete', function (ev, xhr, opt) {
        var u = String((opt && opt.url) || ''), ty = String((opt && (opt.type || opt.method)) || '');
        // só GRAVAÇÕES de grupo: "Grupos - Afiliação" (screen=groups&ajaxaction=village), adicionar por coordenadas, criar/
        // apagar/renomear. Leituras ficam de fora (ajax=load_villages_from_group, que o próprio Agendador usa, e ajaxaction=load_…)
        var aa = (u.match(/[?&]ajaxaction=([a-z_]+)/) || [])[1];
        if (/post/i.test(ty) && /screen=(groups|overview_villages)\b/.test(u) && aa && !/^load/.test(aa)) grpListClear('grupo alterado no jogo (' + aa + ')');
      });
    } catch (e) {}
  }
  /** Lista de aldeias de um grupo, guardada 6 h; esquecida quando o grupo muda no jogo (grpListClear). */
  function groupVillagesCached(group) {
    var c = lsGet('grpList', {}), e = c[group];
    if (e && Date.now() - e.at < 6 * 3600000) return Promise.resolve(e.list);
    return fetchGroupVillages(group).then(function (l) { c = lsGet('grpList', {}); c[group] = { at: Date.now(), list: l }; lsSet('grpList', c); return l; });
  }
  function fetchGroupVillages(group) {
    return new Promise(function (ok, bad) {
      if (botStopped()) return bad(new Error('Agendador parado: verificação do jogo (captcha)'));
      if (!W.TribalWars || !W.TribalWars.post) return bad(new Error('TribalWars.post indisponível'));
      W.TribalWars.post('groups', { ajax: 'load_villages_from_group' }, { group_id: group }, function (r) { ok(r || {}); },
        function (e) { bad(new Error(String((e && e.error) || e || 'não consegui ler o grupo'))); });
    }).then(function (r) {
      var doc = new DOMParser().parseFromString('<table>' + (r.html || '') + '</table>', 'text/html'), seen = {};
      return $qa('[data-village-id]', doc).map(function (a) {
        var tr = a.closest('tr'), c = parseCoord(tr ? tr.textContent : '');
        return { id: +a.dataset.villageId, name: a.textContent.trim(), coord: c ? coordStr(c) : '' };
      }).filter(function (x) { if (!x.id || seen[x.id]) return false; seen[x.id] = 1; return true; });
    });
  }
  /**
   * Equilibrar: para cada aldeia do grupo destino, quanto falta para a meta (contando o que chega) e de quem pedir.
   * 1 POST (lista do grupo) + 1 GET por destino (+1 para devolver o grupo selecionado). Os fornecedores são
   * descontados de um destino para o outro.
   */
  function resBalancePlan(o, progress) {
    return withGroup(o.from, function () { return resBalanceRead(o, progress, String(o.from) !== userGroup()); });
  }
  function resBalanceRead(o, progress, borrowed) {
    var want = o.want, pool = {}, reserve = o.reserve || 0, inc = null;
    return tradesIncoming(borrowed).then(function (m) { inc = m; return inc ? reqGap() : null; }).then(function () { return groupVillagesCached(o.to); }).then(function (dst) {
      if (!dst.length) throw new Error('o grupo destino está vazio');
      var dstIds = dst.map(function (d) { return d.id; }), out = [];
      // 1) lê todos os destinos (o mesmo fornecedor aparece em vários: vale a 1ª leitura, depois o pool descontado)
      return dst.reduce(function (p, d, i) {
        return p.then(function () {
          if (progress) progress(i + 1, dst.length, d);
          return (i ? reqGap() : Promise.resolve()).then(function () { return fetchCall(d.id, o.from); }).then(function (cp) {
            realIncoming(cp, inc);
            var v = cp.village || {};
            var recv = buildRecv();   // esperando recurso pedido pelo 📦: não manda até chegar
            // nada é enviado durante as leituras: vale a leitura MAIS RECENTE de cada fornecedor (o estoque muda enquanto lê)
            cp.sup.forEach(function (s) { if (dstIds.indexOf(s.id) < 0 && !recv[s.id]) pool[s.id] = { id: s.id, name: s.name, res: s.res, cap: s.cap }; });
            var row = { id: d.id, name: v.name || d.name, coord: v.coord || d.coord, have: { wood: v.wood, stone: v.stone, iron: v.iron }, incoming: cp.incoming,
              storage: o.noCap ? 0 : v.storage, storageReal: v.storage, want: want, need: resNeed(want, v, cp.incoming, o.noCap ? 0 : v.storage), sup: cp.sup, sends: [], left: null };
            // aldeia da academia: o que chega vira pacote → meta na proporção do preço do pacote (sem mandar o que já sobra)
            var si = lsGet('snobInfo', null), sbvs = snobCfg().vids;
            if (o.pkt && sbvs.indexOf(String(d.id)) >= 0 && si && si.cost && sbvs.indexOf(String(si.vid)) >= 0) {   // opção da regra (padrão: meta de cada recurso)
              row.pk = si.cost; row.hasIn = {}; RES.forEach(function (r) { row.hasIn[r] = (v[r] || 0) + ((cp.incoming || {})[r] || 0); });
              row.need = packetPlan(row.hasIn, want, o.noCap ? 0 : v.storage, si.cost, [], {}).need;   // o alvo inteiro (sem fornecedores → Pmax)
            }
            out.push(row);
          }, function (e) {
            out.push({ id: d.id, name: d.name, coord: d.coord, error: e.message, need: { wood: 0, stone: 0, iron: 0 }, sends: [], left: { wood: 0, stone: 0, iron: 0 } });
          });
        });
      }, Promise.resolve()).then(function () {
        // 2) não dá para todos? cada destino recebe a mesma fração do que falta (senão o 1º da lista leva tudo)
        var tot = { wood: 0, stone: 0, iron: 0 };
        out.forEach(function (d) { RES.forEach(function (r) { tot[r] += d.need[r]; }); });
        // o que dá de fato: recurso de cada fornecedor limitado pelos comerciantes livres DELE (ver resShareFactor)
        var f = resShareFactor(tot, Object.keys(pool).map(function (k) { return pool[k]; }), reserve), fm = 1;
        // 3) planeja destino a destino, descontando cada fornecedor
        out.forEach(function (d) {
          if (d.error) return;
          var goal = {}; RES.forEach(function (r) { goal[r] = Math.floor(d.need[r] * f[r] * fm); });
          var sup = d.sup.filter(function (s) { return pool[s.id]; }).map(function (s) { return { id: s.id, name: s.name, ms: s.ms, res: pool[s.id].res, cap: pool[s.id].cap }; });
          var plan;
          // por que parou? o que os fornecedores ainda tinham ACIMA da reserva e os comerciantes livres (antes deste destino)
          var av = { wood: 0, stone: 0, iron: 0 }, capS = 0;
          sup.forEach(function (s) { RES.forEach(function (r) { av[r] += Math.max(0, (s.res[r] || 0) - reserve); }); capS += Math.max(0, s.cap || 0); });
          d.why = { av: av, cap: capS, n: sup.length, reserve: reserve };
          if (d.pk) {
            var cs = RES.reduce(function (a, r) { return a + (d.pk[r] || 0); }, 0), lim = null, lv = Infinity;
            RES.forEach(function (r) { if (d.pk[r] > 0 && av[r] / d.pk[r] < lv) { lv = av[r] / d.pk[r]; lim = r; } });
            d.why.lim = cs && capS / cs < lv ? 'cap' : lim;
          }
          if (d.pk) { var pp = packetPlan(d.hasIn, want, d.storage, d.pk, sup, { split: o.split, reserve: reserve, each: o.pktEach }); plan = pp.plan; d.packets = { P: pp.P, Pmax: pp.Pmax }; }
          else plan = sumRes(goal) ? resPlan(goal, sup, { split: o.split, reserve: reserve }) : { sends: [] };
          resApply(sup, plan.sends);
          sup.forEach(function (s) { pool[s.id].res = s.res; pool[s.id].cap = s.cap; });
          plan.sends.forEach(function (x) { x.name = pool[x.id].name; });
          d.sends = plan.sends; d.left = {};
          RES.forEach(function (r) { d.left[r] = d.need[r] - plan.sends.reduce(function (a, x) { return a + x[r]; }, 0); });
          delete d.sup;
        });
        return out;
      });
    });
  }
  /** Por que não chegou na meta: o que havia acima da reserva em quem manda, os comerciantes e (academia) o recurso que limitou os pacotes. */
  function resWhyHtml(d) {
    var y = d.why; if (!y) return '';
    var RN = { wood: 'madeira', stone: 'argila', iron: 'ferro' };
    var head = y.lim === 'cap' ? '👑 limite: <b>comerciantes</b> (' + resFmt(y.cap) + ' de capacidade livre)'
      : y.lim ? '👑 limite: <b>' + RN[y.lim] + '</b>: a proporção do pacote só fecha com o que tem dela; o resto ficaria parado na academia' : '';
    return '<div class="muted" style="margin-top:2px" title="Somando as ' + y.n + ' aldeias do grupo que manda (sem as do grupo que recebe), antes deste destino">' +
      (head ? head + '<br>' : '') + 'acima da reserva (' + resFmt(y.reserve) + ') em ' + y.n + ' aldeia' + (y.n === 1 ? '' : 's') + ': ' + resTriple(y.av) +
      ' · comerciantes ' + resFmt(y.cap) + '</div>';
  }
  function resPlanTable(rows) {
    return '<table class="pv"><tr><th>Destino</th><th>Tem + chegando</th><th>Vai receber</th><th>De</th><th>Chega ≈</th></tr>' + rows.map(function (d) {
      var got = { wood: 0, stone: 0, iron: 0 }, far = 0;
      d.sends.forEach(function (s) { RES.forEach(function (r) { got[r] += s[r]; }); far = Math.max(far, s.ms); });
      var short = sumRes(d.left) > 0;
      if (d.error) return '<tr><td>' + esc(d.name) + ' <span class="muted">' + d.coord + '</span></td><td colspan="4" class="ub-warn">' + esc(d.error) + '</td></tr>';
      // meta acima de 95% do armazém: o que passa disso se perde (o jogo avisa "não cabe"), então vale o limite do armazém
      var c95 = d.storage ? Math.floor(d.storage * 0.95) : 0, lim = c95 && d.want && RES.some(function (r0) { return (d.want[r0] || 0) > c95; });
      return '<tr><td>' + esc(d.name) + ' <span class="muted">' + d.coord + '</span></td><td>' +
        resTriple({ wood: d.have.wood + d.incoming.wood, stone: d.have.stone + d.incoming.stone, iron: d.have.iron + d.incoming.iron }) +
        (lim ? '<div class="muted" title="O que passa do armazém se perde: o Agendador não pede mais que 95% dele">meta limitada pelo armazém: ' + resFmt(c95) + ' (95% de ' + resFmt(d.storage) + ')</div>' : '') +
        (!d.storage && d.storageReal && d.want && RES.some(function (r0) { return (d.want[r0] || 0) > d.storageReal; }) ? '<div class="muted" title="Opção da regra: passar do limite do armazém">meta acima do armazém (' + resFmt(d.storageReal) + '), de propósito</div>' : '') + '</td><td>' +
        (sumRes(got) ? resTriple(got) : '<span class="muted">' + (sumRes(d.need) ? 'nada disponível' : lim ? 'já tem o limite do armazém' : 'já tem') + '</span>') +
        (d.packets ? '<div class="muted" title="Aldeia da academia: o que chega vai na proporção do pacote (sem mandar o recurso que já sobra). Com o que os fornecedores tinham, dá para completar esse tanto de pacotes; a meta permitiria ' + d.packets.Pmax.toFixed(1) + '.">👑 ≈ ' + Math.floor(d.packets.P) + ' pacotes completos</div>' : '') +
        (short ? '<div class="ub-warn" title="Os fornecedores não tinham recurso ou comerciante suficiente">faltam ' + resTriple(d.left) + '</div>' + resWhyHtml(d) : '') +
        '</td><td>' + d.sends.length + (d.sends.length ? ' aldeia' + (d.sends.length > 1 ? 's' : '') : '') + '</td><td>' + (far ? fmtDuration(far) : '') + '</td></tr>';
    }).join('') + '</table>';
  }
  /* ---- regras de equilíbrio: várias, cada uma com grupos, meta, reserva e horários próprios
   * (ex.: +2k → -2k meta 10k 5×/dia; +2k → Pacote meta 100k 2×/dia) ---- */
  /** Regras salvas. Na 1ª vez, o que a 0.16 guardava solto (resFrom, resTo, resTarget, resAuto…) vira a regra 1. */
  function resRules() {
    var c = cfg();
    if (Array.isArray(c.resRules)) return c.resRules;
    // sem regras ainda: a 1ª vem da configuração solta da 0.16 (se houver), grupos em branco = você escolhe
    return [{ id: 'r1', from: c.resFrom || '', to: c.resTo || '', target: c.resTarget, reserve: c.resReserve, split: c.resSplit,
      auto: c.resAuto, n: c.resAutoN, af: c.resAutoFrom, at: c.resAutoTo, times: c.resAutoTimes }];
  }
  function saveRules(list) { setCfg({ resRules: list }); }
  /** Grupos da regra (o id do jogo; vazio = ainda não escolhido). */
  function ruleFrom(r) { return r.from || ''; }   // nada de adivinhar pelo nome do grupo: a regra guarda o id
  function ruleTo(r) { return r.to || ''; }
  function groupName(id) { var g = resGroups().filter(function (x) { return String(x.id) === String(id); })[0]; return g ? g.name : (id ? 'grupo ' + id : '?'); }
  function ruleName(r) {
    var a = ruleFrom(r), b = ruleTo(r);
    if (r.toMode === 'list') { var L = String(r.toList || '').split(/\n/).map(function (x) { return x.trim(); }).filter(Boolean); return (a ? groupName(a) : '(escolha)') + ' → ' + (L.length ? (L.length === 1 ? L[0] : L[0] + ' +' + (L.length - 1)) : '(aldeias/jogadores)'); }
    return !a && !b ? 'nova regra (escolha os grupos)' : (a ? groupName(a) : '(escolha)') + ' → ' + (b ? groupName(b) : '(escolha)');
  }
  /** Opções de execução de uma regra (o que resBalancePlan espera); erro se faltar algo. */
  function ruleOpts(r) {
    var from = ruleFrom(r), to = ruleTo(r), want = parseResTarget(r.target);
    if (!want) throw new Error('meta inválida: ex.: 10k ou 10k 8k 12k');
    if (r.toMode === 'list') {
      if (!from) throw new Error('escolha o grupo que manda');
      if (!String(r.toList || '').trim()) throw new Error('informe as aldeias (coordenadas) ou os jogadores que recebem');
      return { from: from, list: true, want: want, reserve: Math.max(0, parseInt(r.reserve, 10) || 0) };
    }
    if (!from || !to || String(from) === String(to)) throw new Error('escolha dois grupos diferentes');
    return { from: from, to: to, want: want, reserve: Math.max(0, parseInt(r.reserve, 10) || 0), split: r.split || 'prop', pkt: !!r.pkt, pktEach: r.pktMode === 'each', noCap: !!r.noCap };
  }
  function ruleAuto(r) { return { mode: r.auto || 'off', n: r.n, every: r.every, from: r.af, to: r.at, times: r.times }; }
  function ruleWhen(r) {
    if (r.off && r.auto && r.auto !== 'off') return 'desligada';
    return r.auto === 'n' ? (r.n || 1) + '×/dia ' + (r.af || '') + '–' + (r.at || '') : r.auto === 'every' ? 'a cada ' + (r.every || 60) + ' min ' + (r.af || '') + '–' + (r.at || '') : r.auto === 'times' ? (r.times || '').replace(/\s+/g, ' ') : 'só no ▶ Agora';
  }
  /**
   * Seções recolhíveis: cada título .sec filho de `root` ganha ▾/▸ e recolhe o que vem até o próximo título. Lembra
   * (prefKey: {título: 1} recolhido). Clique em botão/link/ⓘ do título não recolhe.
   */
  function foldSections(root, prefKey) {
    if (!root) return;
    var st = prefGet(prefKey, {}) || {}, kids = Array.prototype.slice.call(root.children), cur = null;
    kids.forEach(function (el) {
      if (el.classList.contains('sec')) {
        var key = el.textContent.replace(/[▾▸ⓘ⟳]/g, '').replace(/\s+/g, ' ').trim().slice(0, 40);
        cur = document.createElement('div'); cur.className = 'sec-body'; el.parentNode.insertBefore(cur, el.nextSibling);
        var ar = document.createElement('span'); ar.className = 'sec-ar'; el.insertBefore(ar, el.firstChild);
        el.style.cursor = 'pointer'; el.title = 'Clique para abrir/recolher';
        var body = cur, set = function (f) { body.style.display = f ? 'none' : ''; ar.textContent = f ? '▸ ' : '▾ '; };
        set(!!st[key]);
        el.addEventListener('click', function (e) {
          if (e.target.closest('button, a, select, input, .agtw-i, [data-grp-refresh]') && !e.target.closest('.sec-ar')) return;
          var s2 = prefGet(prefKey, {}) || {}; if (s2[key]) delete s2[key]; else s2[key] = 1; prefSet(prefKey, s2); set(!!s2[key]);
        });
        return;
      }
      if (cur && el.tagName !== 'DATALIST') cur.appendChild(el);
    });
  }
  /* ---- 📤 Distribuir: a seção da aba Recursos (um cartão por distribuição) ---- */
  function distVName(id) { var v = (ui.villages || []).filter(function (x) { return String(x.id) === String(id); })[0]; return v ? v.name + ' (' + v.x + '|' + v.y + ')' : (id ? 'aldeia ' + id : ''); }
  function distResIcons(o, sz) {
    var k = RES.filter(function (r) { return (o || {})[r] > 0; }); if (!k.length) return '<span class="muted">-</span>';
    return k.map(function (r) { return '<span style="white-space:nowrap;margin-right:6px">' + twIcon(r, sz || 14, RES_PT[r]) + ' ' + resFmt(o[r]) + '</span>'; }).join('');
  }
