    log(msg); feedPush(e.err || (e.errs && e.errs.length) ? '⚠' : '📦', (e.name || 'Equilíbrio') + ': ' + (e.err ? e.err : !e.total ? 'nada a enviar' : e.ok + '/' + e.total + ' pedidos · ' + resFmt(e.sent)));
