    var r = { done: 0, from: ok.length ? ok[0].r.from : null, to: last.r ? last.r.to : null, need: last.r ? last.r.need : null, res: last.r ? last.r.res : null, cost: last.r ? last.r.cost : null };
    per.forEach(function (x) { r.done += (x.r && x.r.done) || 0; });
