  function feedCmdIcon(c) { var u = c.units || {}; return u.snob > 0 || /nobre\s*=/.test(String(c.units)) ? '👑' : c.type === 'support' ? '🛡' : '⚔'; }
  /** Frequência curta de um horário automático (para a lista). */
