      var base = 'z-index:10001;overflow:hidden;cursor:pointer;color:#3a2208;font:11px/15px Verdana,Arial,sans-serif;text-align:left;box-sizing:border-box;' +
        'border:1px solid #804000;border-radius:3px;background-color:#efdfb6;background-image:linear-gradient(#f7ecd0,#e9d5a5);box-shadow:inset 0 1px 0 #fff8e4,0 1px 3px rgba(0,0,0,.45);';
