      // a célula dos recursos: a que tem algum span.res (perto de encher o jogo troca a classe daquele recurso: warn/warn_90)
      // recurso cheio troca "res" por "warn" (e perto de encher por "warn_90"): com os 3 cheios não sobra nenhum span.res
      var vn = $q('.quickedit-vn[data-id]', tr), rw = $q('span.res, span.warn, span.warn_90', tr); if (!vn || !rw) return;
