    var cur = $q('#plunder_list_nav strong.paged-nav-item', doc), curN = cur ? (parseInt((cur.textContent.match(/\d+/) || [])[0], 10) || 1) - 1 : 0, maxN = -1;
    $qa('#plunder_list_nav a[href*="Farm_page="], #plunder_list_nav option', doc).forEach(function (el) {
      var m = String(el.getAttribute('href') || el.getAttribute('value') || '').match(/Farm_page=(\d+)/); if (m && +m[1] > maxN) maxN = +m[1];
    });
    var more = maxN > curN || !!(cur && cur.nextElementSibling && /Farm_page=/.test(cur.nextElementSibling.getAttribute('href') || ''));
    // filtros do próprio assistente que ESCONDEM aldeias da lista (aí elas viram "sem info" aqui)
    var ck = function (id) { var el = $q('#' + id, doc); return el ? el.checked || el.hasAttribute('checked') : null; }, hide = [];
    if (ck('attacked_checkbox') === false) hide.push('"Incluir relatórios de aldeias que você está atacando" desmarcada: some toda aldeia com ataque indo ou tropa voltando');
    if (ck('full_losses_checkbox') === false) hide.push('"Incluir relatórios indicando perdas totais" desmarcada');
    if (ck('partial_losses_checkbox') === false) hide.push('"Incluir relatórios indicando perdas parciais" desmarcada');
    if (ck('all_village_checkbox') === true) hide.push('"Mostrar apenas ataques que foram enviados a partir desta aldeia" marcada');
    if (ck('full_hauls_checkbox') === true) hide.push('"Apenas exibir relatórios em que as suas tropas saquearam a capacidade possível de carga total" marcada');
    // unidades marcadas em "Disponibilidade": o jogo projeta os recursos de cada linha até a chegada da mais LENTA delas
