    add('Realizações', function () { return fetchText(gameUrl(GD.village.id, 'info_player', '&mode=awards')).then(function (h) { ecoLootSave(parseAwards(new DOMParser().parseFromString(h, 'text/html'))); }); });
    // estatísticas: o jogo guarda ~40 dias de "aldeias saqueadas", 1 leitura por semana basta
    add('Estatísticas', function () { return fresh(lsGet('ecoFarmAt', 0), 24 * 6.5) && !force ? Promise.resolve(false) : fetchText(gameUrl(GD.village.id, 'info_player', '&mode=stats_own')).then(function (h) { ecoFarmSave(parseFarmDays(h)); lsSet('ecoFarmAt', Date.now()); }); });
