    pb.textContent = pz ? '▶ Continuar' : '⏸ Pausar';
    pb.title = pz ? 'Continua o ciclo de onde parou' : 'Pausa o saque em todas as abas: termina o ataque que está saindo e espera; ciclo novo não começa';
    if (rb) { rb.style.display = pz || rq ? '' : 'none'; rb.disabled = !!rq; rb.textContent = rq ? '⟲ recomeçando…' : '⟲ Recomeçar do zero'; }
