        if (a === 'fold') { fold[r.id] = !fold[r.id]; return render(); }
        if (a === 'on') { if (!r.on && !repReady(r)) return toast('Coloque o jogador que manda e as aldeias de destino', 'bad'); r.on = !r.on; repRulesSave(l); var m = repMeta(); if (r.on && !m.next) { m.next = now(); repMetaSave(m); } return render(); }
        if (a === 'go') return go(r.id);
