      if (!v) { var q = inp.value.trim().toLowerCase(); v = q ? (ui.villages || []).filter(function (x) { return String(x.name).toLowerCase() === q; })[0] : null; }
      if (!v) return toast('Aldeia não encontrada entre as suas (digite o nome ou x|y)', 'bad');
