  /** Soma das tropas de envios (waves) → {u: n}; e por aldeia que manda → {sid: {u: n}}. */
  function supWavesSum(waves) { var s = {}; waves.forEach(function (w) { Object.keys(w.src).forEach(function (sid) { Object.keys(w.src[sid]).forEach(function (u) { s[u] = (s[u] || 0) + w.src[sid][u]; }); }); }); return s; }
