              var done = mine.every(function (w) { return w.done; }), failed = mine.some(function (w) { return w.fail; });
              var stt = done ? '✓' : failed ? '✗ ' + esc(mine.filter(function (w) { return w.fail; })[0].fail) : (ST[en.st] || en.st) + (en.msg && en.st !== 'ok' ? ' <span class="muted">' + esc(en.msg) + '</span>' : '');
              var key = esc(en.id) + '|' + esc(sid);
