      L.push('calib: bias ' + st.bias + ' · variação ±' + (st.spread == null ? '?' : st.spread) + ' · ' + st.used + '/' + st.n + ' · amostras ' + JSON.stringify(readCalib().map(function (x) { return x.b; })));
      L.push('config: look ' + cfg().lookaheadSec + 's · spin ' + cfg().spinMs + ' · offset ' + cfg().manualOffsetMs + ' · autoCalib ' + cfg().autoCalib + ' · pingSeed ' + cfg().autoPingSeed);
      L.push('--- envios (arm=antes de disparar · res=depois) ---');
      d.forEach(function (e) {
        if (e.phase === 'disparo') {
          L.push('CLIQUE ' + e.label + ' [' + e.type + ']  overshoot-clique ' + e.overshootClique + 'ms · hidden=' + e.hidden + ' · keepAlive=' + e.keepAlive);
        } else if (e.phase === 'resultado') {
          L.push('res  ' + e.label + ' [' + e.type + ']  chegou ' + (e.chegadaReal ? fmt(e.chegadaReal) : '?') +
            (e.chegadaAlvo ? ' (alvo ' + fmt(e.chegadaAlvo) + ')' : '') + '  overshoot ' + e.overshootLocal + ' · latência ' + e.latencia + ' · ERRO ' + e.erroFinal);
        } else {
          L.push('arm  ' + e.label + ' [' + e.type + '/' + e.mode + '] →' + e.tgt + '  chegada-alvo ' + fmt(e.cmdTime) +
            ' · durReal ' + Math.round(e.durMs / 1000) + 's (est ' + Math.round(e.estDur / 1000) + 's) · saída ' + fmt(e.sendAt) + ' · corr ' + e.corr);
        }
      });
      L.push('=== fim (' + d.length + ' registros) ===');
      var txt = L.join('\n');
      console.log(txt);
