  function hasNoble(c) { if (c.nobleLoop) return true; try { return splitTrain(c.units).some(function (sp) { return 'snob' in parseUnitSpec(sp).units; }); } catch (x) { return false; } }
  /* ---- 📅 agendamentos da aldeia: no balão do mapa (hover) e na página de informações. Só a fila; sem requisição. ---- */
