    var body = table.tBodies && table.tBodies[0] ? table.tBodies[0] : table;
    var game = Array.prototype.slice.call(body.children).filter(function (r) { return r.cells && r.cells.length >= 3 && !$q('th', r); })
      .map(function (r) { return { tr: r, at: gameRowArrival(r) }; });
