      rows[i.value] = { model: (tr.cells[1] && tr.cells[1].textContent.trim()) || '', orders: (tr.cells[2] && tr.cells[2].textContent.trim()) || '', state: (tr.cells[3] && tr.cells[3].textContent.replace(/\(\s*Pausar\s*\)|\(\s*Próximo\s*\)/g, '').replace(/\s+/g, ' ').trim()) || '' };
