        if (which !== 'troops') p = p.then(function () { return one('am_village'); }).then(function (d) { out.build = gcParseBuild(d); });
        if (which !== 'build') p = p.then(function () { return which ? null : reqGap(); }).then(function () { return one('am_troops'); }).then(function (d) { out.troops = gcParseTroops(d); });
