    if (!units.length || !bodies.length) return null;
    var rowsOf = function (b) { return $qa('tr', b).filter(function (tr) { return $q('td.unit-item', tr); }); };
    var vals = function (tr) { return $qa('td.unit-item', tr).map(function (c) { return parseInt(c.textContent.replace(/\D/g, ''), 10) || 0; }); };
    var zero = function () { return units.map(function () { return 0; }); }, add = function (acc, v) { v.forEach(function (x, i) { if (i < acc.length) acc[i] += x; }); };
