      var L = r[st.side].left, tot = Object.keys(L).reduce(function (a, u) { return a + L[u]; }, 0);
      if (!st.hist.length || st.hist[st.hist.length - 1].n !== st.n) st.hist.push({ n: st.n, left: L, tot: tot, wall: st.side === 'def' && r.surv && r.surv.buildings ? r.surv.buildings.wall : null });
