  /* ---- 🎁 aldeias bônus (fazenda, +30% recursos…) nas listas que não mostram: o ícone vem da Produção (Visualizações), onde o
   * jogo mostra <span class="bonus_icon bonus_icon_N" data-title="…">. Guardado ao abrir a Produção (ou quando o Agendador
   * já a lê); a página que não tem os dados lê a Produção 1 vez (e vale por 7 dias). */
  function bonusCacheFrom(root) {
    var m = lsGet('villBonus', {}) || {}, n = 0;
    $qa('.quickedit-vn[data-id]', root).forEach(function (qe) {
      var id = qe.getAttribute('data-id'), b = $q('.bonus_icon', qe); n++;
      if (b) { var k = (String(b.className).match(/bonus_icon_(\d+)/) || [])[1]; if (k) m[id] = { n: k, t: b.getAttribute('data-title') || '' }; } else delete m[id];
    });
    if (n) { m._at = Date.now(); lsSet('villBonus', m); }
    return n;
  }
  function bonusIconEl(b) {
    var sp = document.createElement('span');
    sp.className = 'bonus_icon bonus_icon_' + b.n + ' agtw-bonus-ic'; sp.title = b.t; sp.setAttribute('data-title', b.t);
    sp.style.cssText = 'display:inline-block;vertical-align:middle;margin-left:3px';
    return sp;
  }
  /** Gerenciar recrutamento (am_troops): o ícone de bônus ao lado de cada aldeia. */
  function recruitBonusMount() {
    if (SCREEN !== 'am_troops') return;
    var paint = function (m) {
      $qa('.village_anchor[data-id]').forEach(function (a) {
        var b = m[a.getAttribute('data-id')]; if (!b || (a.nextElementSibling && a.nextElementSibling.classList.contains('agtw-bonus-ic'))) return;
        a.insertAdjacentElement('afterend', bonusIconEl(b));
      });
    };
    var m = lsGet('villBonus', null);
    if (m && Date.now() - (m._at || 0) < 7 * 86400000) return paint(m);
    if (botStopped()) return m ? paint(m) : null;
    withGroup(0, function () { return fetchText(gameUrl(GD.village.id, 'overview_villages', '&mode=prod&group=0&page=-1')); })
      .then(function (h) { bonusCacheFrom(new DOMParser().parseFromString(h, 'text/html')); paint(lsGet('villBonus', {}) || {}); }, function (e) { log('aldeias bônus:', e.message); if (m) paint(m); });
  }
