      if (k === 'redo') { box.remove(); troopTotalsShow(); return; }
      if (k === 'foot') { troopTotalsFoot(o); b.textContent = $q('#units_table tfoot.agtw-tt-foot') ? '⬆ Tirar da tabela' : '⬇ Pôr na tabela'; return; }
