      pad = document.createElement('div'); pad.className = 'agtw-selpad';
      pad.style.cssText = 'position:absolute;left:0;top:0;right:0;bottom:0;z-index:50;cursor:crosshair;touch-action:none;background:transparent';
      host.appendChild(pad);
